<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Domain;

use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ValueObject\ResponseMode;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ValueObject\ResponseType;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ValueObject\UiLocale;

/**
 * Immutable value object capturing all parameters of an in-progress OIDC authorization request.
 *
 * Assembled once from the incoming HTTP request at the entry point of the authorization flow and
 * passed through every step handler without modification. Centralises all query-string, cookie, and
 * header extraction so that individual step handlers do not depend on the raw HTTP request object
 * beyond this context being available.
 *
 * The fromRequest() factory handles audience normalisation (comma-separated string or array),
 * constructs the tenant-scoped issuer URL, and reads the tenant-specific session cookie.
 * PKCE parameters are captured as nullable fields; null means the client did not include PKCE,
 * which is permitted for confidential clients but should be enforced for public ones.
 */
final class OidcFlowContext
{
    /**
     * Tenant identifier extracted from the URL path of the authorization endpoint.
     * Determines which identity store, signing keys, and policies are applied to this flow.
     */
    public readonly string $tenant;

    /**
     * OAuth client_id parameter supplied by the Relying Party in the authorization request.
     * Used to load and validate the registered client configuration from the client store.
     */
    public readonly string $clientId;

    /**
     * Redirect URI supplied by the client; must match a registered URI before tokens are issued.
     * Carried through the flow so the final response can redirect to the correct destination.
     */
    public readonly string $redirect;

    /**
     * Space-separated scope string requested by the client in the authorization request.
     * Subject to policy enforcement; the granted scopes may be a subset of this value.
     */
    public readonly string $scope;

    /**
     * OAuth response_type parameter (e.g., "code" or "code id_token"), normalised as a set by
     * fromRequest() (ResponseType). Validated against the supported and the client's registered
     * response types before the flow proceeds.
     */
    public readonly string $responseType;

    /**
     * Opaque state value supplied by the client to prevent CSRF attacks.
     * Echoed back verbatim in the redirect response without interpretation by the IdP.
     */
    public readonly string $state;

    /**
     * Nonce value supplied by the client for replay protection in ID tokens.
     * Included in the issued ID token's nonce claim so the client can verify freshness.
     */
    public readonly string $nonce;

    /**
     * List of resource server audience identifiers for which the access token should be valid.
     * Normalised from either a comma-separated query parameter string or a repeated parameter array.
     */
    public readonly array $audiences;

    /**
     * Requested prompt behaviour (e.g., "none", "login", "consent") controlling the UI flow.
     * An empty string means the IdP may apply its default behaviour.
     */
    public readonly string $prompt;

    /**
     * Language of the login UI: the first supported one of ui_locales, then of Accept-Language
     * (UiLocale). Only for this request; never stored in the user's profile.
     */
    public readonly string $locale;

    /**
     * Base URL of the authorization server without a trailing slash.
     * Used to construct issuer URLs, cookie names, and absolute redirect targets.
     */
    public readonly string $baseUrl;

    /**
     * Tenant-scoped issuer URL derived from baseUrl and the tenant identifier.
     * Included in the iss claim of all tokens issued during this flow.
     */
    public readonly string $issuer;

    /**
     * Value of the tenant-specific AUTH_SESSION_ID cookie if present in the request.
     * Non-null means the browser carries an existing session that may be reused.
     */
    public readonly ?string $sessionId;

    /**
     * Value of the PRE_SESSION_ID cookie representing a partially completed login session.
     * Non-null when the user was redirected mid-flow (e.g., after MFA) and needs to resume.
     */
    public readonly ?string $preSessionId;

    /**
     * PKCE code challenge value provided by the client for public client flows.
     * Null when the client did not include PKCE; enforcement policy is applied upstream.
     */
    public readonly ?string $codeChallenge;

    /**
     * PKCE code challenge method; only "S256" is accepted (task 034).
     * Null when no challenge was provided; always read together with codeChallenge.
     */
    public readonly ?string $codeChallengeMethod;

    /**
     * Signed reference to a consumed PAR or JAR request (AuthorizationRequestResolver), or null for
     * a request taken from the query. URLs back to /authorize must carry it as request_ref.
     */
    public readonly ?string $requestRef;

    /**
     * The ui_locales the client requested, as sent, or null when it requested none. URLs back to
     * /authorize must carry it so every step keeps the language.
     */
    public readonly ?string $uiLocales;

    /**
     * The response_mode the client requested, as sent, or null when it requested none; see
     * responseMode() for the mode actually used. URLs back to /authorize must carry it.
     */
    public readonly ?string $requestedResponseMode;

    public function __construct(
        string $tenant,
        string $clientId,
        string $redirect,
        string $scope,
        string $responseType,
        string $state,
        string $nonce,
        array $audiences,
        string $prompt,
        string $locale,
        string $baseUrl,
        string $issuer,
        ?string $sessionId,
        ?string $preSessionId,
        ?string $codeChallenge,
        ?string $codeChallengeMethod,
        ?string $requestRef = null,
        ?string $uiLocales = null,
        ?string $requestedResponseMode = null,
    ) {
        $this->tenant = $tenant;
        $this->clientId = $clientId;
        $this->redirect = $redirect;
        $this->scope = $scope;
        $this->responseType = $responseType;
        $this->state = $state;
        $this->nonce = $nonce;
        $this->audiences = $audiences;
        $this->prompt = $prompt;
        $this->locale = $locale;
        $this->baseUrl = $baseUrl;
        $this->issuer = $issuer;
        $this->sessionId = $sessionId;
        $this->preSessionId = $preSessionId;
        $this->codeChallenge = $codeChallenge;
        $this->codeChallengeMethod = $codeChallengeMethod;
        $this->requestRef = $requestRef;
        $this->uiLocales = $uiLocales;
        $this->requestedResponseMode = $requestedResponseMode;
    }

    /**
     * Mode of the authorization response: the requested one or the default for the response type.
     * When the requested mode is not valid for it, the default, so the invalid_request error can
     * still be returned; rejecting such a request is up to the authorization endpoint.
     */
    public function responseMode(): ResponseMode
    {
        $responseType = ResponseType::fromString($this->responseType);
        return ResponseMode::resolve($responseType, $this->requestedResponseMode) ?? ResponseMode::defaultFor($responseType);
    }

    /**
     * True for a plain code delivered in the query: the only authorization response a channel
     * outside this flow can give, such as the magic link sent by email, which redirects with a
     * code and nothing else (EP-08).
     */
    public function isCodeInQuery(): bool
    {
        return $this->responseType === 'code' && $this->responseMode() === ResponseMode::Query;
    }

    /**
     * Parameters every URL back to /authorize must carry so the next step continues this request:
     * the reference of a PAR/JAR request, the requested UI language and response mode.
     *
     * @return array<string, string>
     */
    public function continuationParams(): array
    {
        return array_filter([
            ResolvedAuthorizationRequest::REFERENCE_PARAM => $this->requestRef,
            'ui_locales' => $this->uiLocales,
            'response_mode' => $this->requestedResponseMode,
        ], static fn (?string $value): bool => $value !== null && $value !== '');
    }

    /**
     * Constructs an OidcFlowContext by extracting all relevant parameters from an HTTP request.
     * Reads query params, cookies, and the Accept-Language header and derives the issuer and base URL from context.
     * The query must already hold the resolved authorization parameters (AuthorizationRequestResolver).
     */
    public static function fromRequest(ServerRequestInterface $request, string $tenant, Context $context, ?string $requestRef = null): self
    {
        $query = $request->getQueryParams();
        $cookies = $request->getCookieParams();

        $baseUrl = $context->getBaseUrl();
        $issuer = $context->getIssuer($tenant);
        $audiences = self::normalizeAudiences($query['audience'] ?? null);

        return new self(
            tenant: $tenant,
            clientId: (string) ($query['client_id'] ?? ''),
            redirect: (string) ($query['redirect_uri'] ?? ''),
            scope: (string) ($query['scope'] ?? ''),
            responseType: ResponseType::fromString((string) ($query['response_type'] ?? ''))->toString(),
            state: (string) ($query['state'] ?? ''),
            nonce: (string) ($query['nonce'] ?? ''),
            audiences: $audiences,
            prompt: (string) ($query['prompt'] ?? ''),
            locale: UiLocale::negotiate((string) ($query['ui_locales'] ?? ''), $request->getHeaderLine('accept-language')),
            baseUrl: $baseUrl,
            issuer: $issuer,
            sessionId: $cookies['AUTH_SESSION_ID_' . strtoupper($tenant)] ?? null,
            preSessionId: $cookies['PRE_SESSION_ID'] ?? null,
            codeChallenge: isset($query['code_challenge']) && $query['code_challenge'] !== '' ? (string) $query['code_challenge'] : null,
            codeChallengeMethod: isset($query['code_challenge_method']) && $query['code_challenge_method'] !== '' ? (string) $query['code_challenge_method'] : null,
            requestRef: $requestRef,
            uiLocales: isset($query['ui_locales']) && $query['ui_locales'] !== '' ? (string) $query['ui_locales'] : null,
            requestedResponseMode: isset($query['response_mode']) && $query['response_mode'] !== '' ? (string) $query['response_mode'] : null,
        );
    }

    /**
     * @return string[]
     *
     * @psalm-return list<non-empty-string>
     */
    public static function normalizeAudiences(mixed $audience): array
    {
        if (is_array($audience)) {
            $raw = $audience;
        } elseif (is_string($audience)) {
            $raw = $audience === '' ? [] : explode(',', $audience);
        } else {
            $raw = [];
        }

        $items = array_map(static fn ($value): string => trim((string) $value), $raw);
        $items = array_filter($items, static fn (string $value): bool => $value !== '');

        return array_values(array_unique($items));
    }
}
